 for(const b of document.querySelectorAll('[data-topic]')){const on=b.dataset.topic===topic;b.setAttribute('aria-pressed',on);b.classList.toggle('selected',on);}
 for(const action of ['favorites','recent']){const b=$('.filters [data-action="'+action+'-home"]');if(b){const on=filter===(action==='favorites'?'favorites':'recent');b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on);}}
