function renderComparison(d){const el=$('#comparison');if(!el)return;if(!pinned){el.innerHTML='';return}const a=evaluate(active.id,pinned.state,pinned.config);el.innerHTML=`<div class="comparison-card"><div class="comparison-heading"><b>A đã lưu ↔ B hiện tại</b><div><button data-action="restore-pin">Về A</button><button data-action="swap-pin">Đổi A/B</button><button data-action="clear-pin" aria-label="Đóng so sánh">×</button></div></div><div class="comparison-values">${meters[active.id].map(m=>{const x=meterValue(a,pinned.state,m),y=meterValue(d,state,m),delta=x===null||y===null?null:(y-x)*m.scale,unit=active.id==='electric'&&['magnitude','z'].includes(m.key)?d?.unit:m.unit;return `<div><span>${m.label}</span><strong>${fmt(x===null?NaN:x*m.scale,m.digits)} → ${fmt(y===null?NaN:y*m.scale,m.digits)} <small>${unit}</small></strong><small>Δ ${delta===null?'—':(delta>0?'+':'')+fmt(delta,m.digits)}</small></div>`}).join('')}</div></div>`;}
function numericColumns(){return active.headers.map((h,i)=>({h,i})).filter(({i})=>!rows.length||rows.some(r=>typeof r.values[i]==='number'));}
function renderPanel(){if(panel==='discover'){$('#panel').innerHTML=discoveryMarkup(active,prefs,saved[active.id]);}else if(panel==='data'){$('#panel').innerHTML=`<div class="data-layout"><details class="chart-card" id="chartPanel" ${prefs.layout.chartCollapsed?'':'open'}><summary>Đồ thị <span>Mở / đóng</span></summary><div class="chart-content"><div class="panel-heading"><h2>Quan hệ đại lượng</h2><select id="graphMode" aria-label="Loại đồ thị"><option value="model" ${config.graphMode!=='measured'?'selected':''}>Mô hình</option><option value="measured" ${config.graphMode==='measured'?'selected':''}>Trạng thái đã ghi</option></select></div><div id="graphOptions"></div><div id="graph" tabindex="0" role="group" aria-label="Đồ thị tương tác"></div><div class="resize-handle height-resizer" role="separator" tabindex="0" data-resize="chartHeight" aria-orientation="horizontal" aria-label="Chiều cao đồ thị"></div><div id="legend" class="legend"></div><div id="fitResult" class="fit-result"></div><p class="analysis-caption">Số liệu từ mô hình lý tưởng. Chạm đồ thị mô hình để khảo sát tại một điểm. Chọn chấm đã ghi để đối chiếu trạng thái.</p></div></details><div class="resize-handle data-resizer" role="separator" tabindex="0" data-resize="dockWidth" aria-orientation="vertical" aria-label="Độ rộng bảng số liệu"> </div><details class="table-card" id="tablePanel" ${prefs.layout.tableCollapsed?'':'open'}><summary>Bảng trạng thái <span id="rowCount">${rows.length}</span><b>Mở / đóng</b></summary><div class="panel-heading"><span>Dữ liệu mô phỏng</span><button class="quiet-button" data-action="csv">CSV ↓</button></div><div class="table-scroll" tabindex="0" aria-label="Vùng cuộn bảng số liệu"><table><caption class="sr-only">Các trạng thái đã ghi của ${esc(active.shortTitle)}</caption><thead><tr><th scope="col">Lần</th>${active.headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody id="rows"></tbody></table><div id="emptyData" class="empty-data">Ghi điểm hoặc quét biến để thu số liệu.</div></div><div class="resize-handle height-resizer" role="separator" tabindex="0" data-resize="tableHeight" aria-orientation="horizontal" aria-label="Chiều cao bảng đo"></div><div class="table-actions"><button data-action="export-session">Tải phiên ↓</button><button data-action="import-session">Mở phiên ↑</button><button data-action="undo">Bỏ dòng cuối</button><button data-action="clear">Xóa bảng</button></div></details></div>`;renderRows();renderGraphOptions();renderGraph();}else if(panel==='tasks'){$('#panel').innerHTML=`<section class="task-panel"><div><h2>Từ dữ liệu đến kết luận</h2><ol>${active.tasks.map(t=>`<li>${t}</li>`).join('')}</ol></div><div><label for="notes">Nhận xét của bạn</label><textarea id="notes" data-notes-for="${active.id}" placeholder="Dự đoán · Bằng chứng · Kết luận">${esc(saved[active.id]?.notes||'')}</textarea><button class="quiet-button" data-action="notes">Tải ghi chép ↓</button></div></section>`;$('#notes').value=saved[active.id]?.notes||'';}else if(panel==='theory'){$('#panel').innerHTML=`<section class="formula-panel">${formulaMarkup(active)}<details><summary>Điều kiện & giải thích</summary><p>${active.theory}</p><p>${active.limit}</p></details><button class="quiet-button" data-action="speak-intro">${icon('voice')}Nghe hướng dẫn</button></section>`;}else{$('#panel').innerHTML=`<div class="source-cards">${(sources[active.id]||[]).map(r=>`<a href="${r.url}" target="_blank" rel="noopener noreferrer"><span>${r.publisher}</span><h3>${r.title} ↗</h3><p>${esc(r.kind)}</p>${r.note?`<span class="source-scope">${esc(r.note)}</span>`:''}</a>`).join('')}</div><p class="source-note">Số liệu được tính từ mô hình. Các giả định nằm trong tab Mô hình.</p>`;}}
function renderGraphOptions(){const el=$('#graphOptions');if(!el)return;if(config.graphMode==='measured'){const cols=numericColumns();config.graphX=cols.some(q=>q.i===+config.graphX)?+config.graphX:(cols[0]?.i??0);config.graphY=cols.some(q=>q.i===+config.graphY)?+config.graphY:(cols[1]?.i??1);const select=(key,label)=>`<label>${label}<select id="${key}">${cols.map(q=>`<option value="${q.i}" ${config[key]===q.i?'selected':''}>${q.h}</option>`).join('')}</select></label>`;el.innerHTML=`<div class="axis-controls">${select('graphX','Trục x')}${select('graphY','Trục y')}<label class="check"><input id="fitLine" type="checkbox" ${config.fitLine?'checked':''}>Khớp mô hình</label><div class="fit-controls" ${config.fitLine?'':'hidden'}><label for="fitModel">Dạng quan hệ</label><select id="fitModel" aria-label="Dạng quan hệ khớp dữ liệu">${fitModels.map(m=>`<option value="${m.key}" ${(config.fitModel||'linear')===m.key?'selected':''}>${m.label}</option>`).join('')}</select></div></div>`;}else el.innerHTML=active.id==='gas'?`<select id="gasAxis" aria-label="Trục đồ thị"><option value="tK" ${config.gasAxis==='tK'?'selected':''}>p theo T</option><option value="v" ${config.gasAxis==='v'?'selected':''}>p theo V</option></select>`:'';}
function renderRows(){
 updateMeasurementCount();if(!$('#rows'))return;
 $('#rows').innerHTML=rows.map((r,i)=>{const canRestore=restorableRow(active,r);return `<tr class="${i===selectedRow?'selected-row':''}" aria-selected="${i===selectedRow}"><td class="row-index"><button data-row="${i}" ${canRestore?'':'disabled'} aria-label="${canRestore?'Xem lại lần '+(i+1):'Lần '+(i+1)+' thiếu thiết lập gốc; chỉ xem số liệu'}" title="${canRestore?'Khôi phục trạng thái đã ghi':'Không đủ thiết lập để khôi phục mô hình'}">${i+1}${canRestore?'<span aria-hidden="true">↗</span>':''}</button></td>${r.values.map(v=>`<td>${v===null?'—':typeof v==='number'?fmt(v,Math.abs(v)<.1?4:3):esc(v)}</td>`).join('')}</tr>`}).join('');
 $('#rowCount').textContent=rows.length;$('#emptyData').hidden=!!rows.length;
 $('#emptyData').innerHTML=deletedRows?.id===active.id?`Đã xóa ${deletedRows.rows.length} dòng đo. <button class="button secondary" data-action="restore-data">Khôi phục bảng vừa xóa</button>`:'<span>Chưa có số liệu.</span> Ghi một trạng thái để bắt đầu đối chiếu.<button class="button secondary" data-action="record">＋ Ghi điểm đầu tiên</button>';
 for(const action of ['csv','clear','undo'])for(const b of document.querySelectorAll('[data-action="'+action+'"]'))b.disabled=!rows.length;
}

function renderGraph(){if(!$('#graph')||!active)return;const g=config.graphMode==='measured'?tableGraph(active,rows,config.graphX??0,config.graphY??1,config.fitLine?(config.fitModel||'linear'):false):graphFor(active,state,getData(),config,rows);if(pinned&&config.graphMode!=='measured'){const a=graphFor(active,pinned.state,evaluate(active.id,pinned.state,pinned.config),pinned.config,[]);g.series.push(...a.series.map(q=>({...q,label:'A · '+q.label,color:'#ab6588',dashed:true})));g.ymin=Math.min(g.ymin,a.ymin);g.ymax=Math.max(g.ymax,a.ymax);g.xmin=Math.min(g.xmin,a.xmin);g.xmax=Math.max(g.xmax,a.xmax);}if($('#fitResult')){$('#fitResult').innerHTML=config.graphMode==='measured'&&config.fitLine?fitSummary(g.regression)+auditConditions():'';}const w=520,h=330,m={l:72,r:20,t:30,b:60},pw=w-m.l-m.r,ph=h-m.t-m.b,xx=x=>m.l+(x-g.xmin)/(g.xmax-g.xmin)*pw,yy=y=>h-m.b-(y-g.ymin)/(g.ymax-g.ymin)*ph;graphLayout=config.graphMode==='measured'?null:{g,w,h,m,pw,ph,key:graphParameter(active,config)};let grid='';for(let j=0;j<=4;j++){const x=g.xmin+(g.xmax-g.xmin)*j/4,y=g.ymin+(g.ymax-g.ymin)*j/4;grid+=`<path d="M${xx(x)} ${m.t}v${ph}M${m.l} ${yy(y)}h${pw}" stroke="#e5edf5"/><text x="${xx(x)}" y="${h-m.b+24}" text-anchor="middle">${fmt(x,Math.abs(g.xmax-g.xmin)<3?2:1)}</text><text x="${m.l-12}" y="${yy(y)+6}" text-anchor="end">${fmt(y,Math.abs(g.ymax-g.ymin)<3?2:1)}</text>`;}$('#graph').innerHTML=`<svg viewBox="0 0 ${w} ${h}" aria-label="${g.yLabel} theo ${g.xLabel}"><defs><clipPath id="plotClip"><rect x="${m.l}" y="${m.t}" width="${pw}" height="${ph}"/></clipPath></defs>${grid}<path d="M${m.l} ${m.t}v${ph}h${pw}" stroke="#8298af" fill="none"/><g clip-path="url(#plotClip)">${g.series.map(s=>s.discrete?s.data.filter(p=>p.every(Number.isFinite)).map(([x,y])=>`<circle cx="${xx(x)}" cy="${yy(y)}" r="4" fill="${s.color}"/>`).join(''):segments(s.data).map(part=>`<polyline points="${part.map(([x,y])=>xx(x)+','+yy(y)).join(' ')}" stroke="${s.color}" fill="none" stroke-width="3" ${s.dashed?'stroke-dasharray="7 5"':''}/>`).join('')).join('')}${g.points.map(([x,y],i)=>{const row=g.pointRows?.[i],selected=row===selectedRow,can=restorableRow(active,rows[row]);return `<circle data-graph-row="${row}" class="recorded-point ${selected?'selected-point':''}" role="button" tabindex="0" aria-label="Lần ${row+1}: ${fmt(x)}, ${fmt(y)}. ${can?'Xem lại trạng thái':'Thiếu thiết lập gốc'}" aria-pressed="${selected}" cx="${xx(x)}" cy="${yy(y)}" r="${selected?8:6}" fill="${selected?'#247b65':'#a5632c'}" stroke="white" stroke-width="2"><title>Lần ${row+1} · ${can?'Chọn để đối chiếu':'Chỉ có số liệu'}</title></circle>`;}).join('')}${g.current.map(([x,y])=>`<circle cx="${xx(x)}" cy="${yy(y)}" class="current-point" pointer-events="none" r="4" fill="#3577dd" stroke="white" stroke-width="2"/>`).join('')}</g><text x="${m.l+pw/2}" y="${h-8}" text-anchor="middle">${esc(g.xLabel)}</text><text x="18" y="${m.t+ph/2}" text-anchor="middle" transform="rotate(-90 18 ${m.t+ph/2})">${esc(g.yLabel)}</text></svg>`;$('#legend').innerHTML=g.series.map(s=>`<span><i style="background:${s.color}"></i>${s.label}</span>`).join('')+'<span><i style="background:#ef9956"></i>Trạng thái đã ghi</span>';}
function download(content,name,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);}
function record(){const d=getData();if(!d){toast('Đưa điểm đo ra xa nguồn ít nhất 1,2 cm.');return}if(rows.length>=500){toast('Đã có 500 dòng. Tải phiên hoặc CSV rồi tạo bảng mới.');return}rows.push({recordedAt:new Date().toISOString(),values:tableValues(active.id,state,d,config),s:{...state},d:structuredClone(d),c:structuredClone(config)});save();updateMeasurementCount();if(panel==='data'){renderRows();renderGraph();}toast(`Đã ghi lần ${rows.length}`);if(mode==='explore'){prefs.layout.dockCollapsed=false;mode='measure';panel='data';document.querySelectorAll('[data-mode]').forEach(v=>{const on=v.dataset.mode===mode;v.classList.toggle('selected',on);v.setAttribute('aria-pressed',on)});document.querySelectorAll('[data-panel]').forEach(v=>{const on=v.dataset.panel===panel;v.classList.toggle('selected',on);v.setAttribute('aria-pressed',on)});renderPanel();applyLayout();}}
function auditConditions(){if(rows.length<2)return '';const changing=active.params.filter(p=>tableColumnFor(active,p.key)!==config.graphX&&rows.some(r=>r.s&&r.s[p.key]!==rows[0].s?.[p.key])).map(p=>p.label);if(rows.some(r=>r.c&&['mode','capMode'].some(k=>r.c[k]!==rows[0].c?.[k])))changing.push('Chế độ mô hình');return changing.length?`<p class="analysis-notice">Tập số liệu đổi thêm: ${changing.map(esc).join(', ')}. Hãy cân nhắc các biến này khi diễn giải phép khớp.</p>`:'';}
function exportReport(){save();const priorPanel=panel;if(panel!=='data'){panel='data';renderPanel();}const audit=$('.analysis-notice')?.textContent||'';const fit=config.graphMode==='measured'&&config.fitLine?tableGraph(active,rows,config.graphX??0,config.graphY??1,config.fitModel||'linear').regression:null;const graph=$('#graph svg')?.outerHTML||'';const html=reportMarkup({experiment:active,state,rows,config,fit,audit,notes:saved[active.id]?.notes||'',graph,sources:sources[active.id]||[],date:new Date().toLocaleString('vi-VN')});if(priorPanel!=='data'){panel=priorPanel;renderPanel();}download(html,active.id+'-bao-cao.html','text/html;charset=utf-8');toast('Đã tạo báo cáo. Mở tệp đã lưu để xem, in hoặc lưu PDF.');}
function exportCSV(){if(!rows.length){toast('Ghi ít nhất một dòng số liệu.');return}const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const csv=[['Lần',...active.headers],...rows.map((r,i)=>[i+1,...r.values])].map(r=>r.map(cell).join(',')).join('\r\n');download('\ufeff'+csv,active.id+'-so-lieu.csv','text/csv;charset=utf-8');}
function stopTone(){tone.stop();const b=$('#toneButton');if(b)b.textContent='♪ Nghe âm';}
function speak(text,clips=[]){stopTone();const result=narrator.speak(text,clips);if(!result.ok)toast(result.reason);}
function openDialog(title,content){const dialog=$('#dialog');if(!dialog.open)dialogReturn=document.activeElement;$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=content;if(!dialog.open)dialog.showModal();}
function restoreDialogFocus(){const target=dialogReturn?.isConnected?dialogReturn:$('#lessonTitle')||$('#search')||$('#main');target?.focus?.({preventScroll:true});dialogReturn=null;}
function settings(voiceOnly=false){narrator.refresh();openDialog(voiceOnly?'Giọng đọc tiếng Việt':'Cài đặt',`${voiceOnly?'':`<label class="setting">Hiệu ứng giao diện<input type="checkbox" id="motion" ${prefs.motion?'checked':''}></label><label class="setting">Chất lượng 3D<select id="quality"><option value="high" ${prefs.quality==='high'?'selected':''}>Cao · bóng đổ mịn</option><option value="low" ${prefs.quality==='low'?'selected':''}>Nhẹ · tiết kiệm máy</option></select></label><label class="setting">Cỡ chữ<select id="textSize"><option value="1" ${+prefs.textSize===1?'selected':''}>Lớn</option><option value="1.15" ${+prefs.textSize===1.15?'selected':''}>Rất lớn</option></select></label>`}<label class="setting">Giọng tiếng Việt<select id="voiceName"></select></label><label class="setting">Tốc độ đọc<select id="voiceRate">${[.8,.9,.95,1,1.1,1.2].map(v=>`<option value="${v}" ${+prefs.rate===v?'selected':''}>${String(v).replace('.',',')}×</option>`).join('')}</select></label><p class="setting-note" id="voiceAvailability"></p><div class="voice-test"><button class="button secondary" data-action="voice-preview">▶ Nghe thử</button><button data-action="refresh-voices">↻ Làm mới giọng</button><button data-action="speech-stop">Dừng đọc</button></div><button class="button primary" data-action="close-dialog">Xong</button>`);updateVoiceChoices(narrator.status());}
function route(){if(location.hash==='#main'&&document.querySelector('.home,.lab,.source-page'))return;if(location.hash==='#library'&&!active&&$('#library')){$('#library').scrollIntoView({behavior:prefs.motion?'smooth':'auto'});return}save();running=false;stopTone();narrator.stop();stopThumbnails();if(location.hash==='#sources')stopBanner();const [id,query='']=location.hash.replace(/^#lab\//,'').split('?');const e=experiments.find(e=>e.id===id);if(e){renderLab(e);const input=new URLSearchParams(query).get('s');if(input&&input.length<10000){try{const q=JSON.parse(input);state=clampState(e,{...initialState(e),...q.state});config.mode=[0,1,2,3].includes(q.mode)?q.mode:0;config.capMode=q.capMode==='discharge'?'discharge':'charge';$('.controls').innerHTML=renderControls();syncControls();refresh();save();toast('Đã mở thiết lập từ đường dẫn.');}catch{toast('Thiết lập trong đường dẫn không hợp lệ.');}}}else if(location.hash==='#sources'){viewer?.dispose();viewer=null;heroState=null;active=null;$('#main').innerHTML=`<div class="source-page"><a class="back" href="#">← Thư viện</a><h1>Nguồn học liệu</h1><p><a href="audio/vi13/NOTICE.txt" target="_blank" rel="noopener">Nguồn giọng đọc tiếng Việt ↗</a></p><p>Số liệu được tính từ mô hình. Xem điều kiện áp dụng trong từng bài.</p><section class="international-sources"><h2>Giáo trình & tài liệu quốc tế</h2><p>Nguồn nền tảng, tài liệu thực hành và cơ sở dữ liệu được phân biệt theo mục đích sử dụng. Các tài liệu bổ sung được tra cứu ngày ${internationalChecked}.</p><ul>${internationalReferences.map(r=>`<li><a href="${r.url}" target="_blank" rel="noopener noreferrer">${esc(r.publisher)} · ${esc(r.title)} ↗</a><span class="source-kind">${esc(r.kind)}</span><span class="source-scope">${esc(r.note)}</span></li>`).join('')}</ul></section><h2>Nguồn theo thí nghiệm</h2>${experiments.map(e=>`<details><summary>${e.shortTitle}</summary>${(sources[e.id]||[]).map(r=>`<a href="${r.url}" target="_blank" rel="noopener noreferrer">${esc(r.publisher)} · ${esc(r.title)} ↗</a><span class="source-scope">${esc(r.kind)}${r.note?' · '+esc(r.note):''}</span>`).join('')}</details>`).join('')}</div>`;window.scrollTo(0,0);}else renderHome();if(location.hash==='#library')$('#library')?.scrollIntoView({behavior:prefs.motion?'smooth':'auto'});if($('#dialog').open)$('#dialog').close();}
function importedConfig(raw={}){const out=structuredClone(defaults);out.mode=[0,1,2,3].includes(raw.mode)?raw.mode:0;out.capMode=raw.capMode==='discharge'?'discharge':'charge';out.gasAxis=raw.gasAxis==='v'?'v':'tK';for(const key of Object.keys(out.switches))if(typeof raw.switches?.[key]==='boolean')out.switches[key]=raw.switches[key];if(active.params.some(p=>p.key===raw.dragKey&&p.key!=='t'))out.dragKey=raw.dragKey;out.graphMode=raw.graphMode==='measured'?'measured':'model';for(const key of ['graphX','graphY'])if(Number.isInteger(raw[key])&&raw[key]>=0&&raw[key]<active.headers.length)out[key]=raw[key];out.fitLine=!!raw.fitLine;out.fitModel=fitModels.some(m=>m.key===raw.fitModel)?raw.fitModel:'linear';out.paramWindows=revealParameterWindows(active,state,raw.paramWindows);out.loop=!!raw.loop;out.guideStep=[0,1,2].includes(raw.guideStep)?raw.guideStep:0;return out;}
function sweepParameters(){const list=active.params.filter(p=>p.key!=='t');if(!staticIds.has(active.id)&&!active.visualOnly)list.push({key:'t',label:'Thời gian',unit:'s',min:0,max:duration(active,state,getData()),step:.001});return list;}
function sweepFixed(key){return active.params.filter(p=>p.key!==key&&p.key!=='t').map(p=>`${esc(p.label)} = <b>${fmt(state[p.key],p.digits)} ${esc(p.unit)}</b>`).join(' · ')+(key!=='t'?` · t = <b>${fmt(state.t||0)} s</b>`:'');}
function sweepDialog(){const key=config.dragKey||coreParams(active)[0]?.key,p=sweepParameters().find(p=>p.key===key);openDialog('Giao thức khảo sát',`<label class="setting">Biến quét<select id="sweepKey">${sweepParameters().map(p=>`<option value="${p.key}" ${p.key===key?'selected':''}>${p.label} (${p.unit||'không đơn vị'})</option>`).join('')}</select></label><div class="sweep-range"><label>Từ<input id="sweepStart" type="number" value="${p.min}" step="any"></label><label>Đến<input id="sweepEnd" type="number" value="${p.max}" step="any"></label></div><label class="setting">Số trạng thái<select id="sweepCount">${[5,10,15,20,25].map(n=>`<option ${n===10?'selected':''}>${n}</option>`).join('')}</select></label><p class="sweep-fixed" id="sweepFixed">Giữ cố định: ${sweepFixed(key)}</p><p class="setting-note">Quét một biến, lưu thiết lập của từng trạng thái. Số liệu tính từ mô hình lý tưởng.</p><button data-action="run-sweep" class="button primary">Thu số liệu</button>`);}
