function moveLab(direction){save();const list=pathFilter===null?experiments:paths[pathFilter].ids.map(id=>experiments.find(e=>e.id===id)),i=list.findIndex(e=>e.id===active.id);location.hash='#lab/'+list[(i+direction+list.length)%list.length].id;}
