document.addEventListener('pointerdown',e=>{const handle=e.target.closest('[data-resize]');if(handle){const key=handle.dataset.resize;resizeDrag={key,start:key.endsWith('Height')?e.clientY:e.clientX,value:prefs.layout[key],pointerId:e.pointerId};handle.setPointerCapture?.(e.pointerId);e.preventDefault();return;}if(e.target.closest('[data-graph-row]'))return;const graph=e.target.closest('#graph');if(!graph||!graphLayout?.key||!active||panel!=='data')return;const svg=graph.querySelector('svg');if(!svg)return;const rect=svg.getBoundingClientRect(),p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const matrix=svg.getScreenCTM();if(!matrix)return;const point=p.matrixTransform(matrix.inverse()),{g,m,pw,key}=graphLayout,f=(point.x-m.l)/pw;if(f<0||f>1)return;let value=g.xmin+f*(g.xmax-g.xmin);if(active.id==='sound')value/=1000;if(key==='t'){running=false;state.t=Math.max(0,Math.min(duration(active,state,getData()),value));refresh();save();}else changeState(key,value);});
