document.addEventListener('toggle',e=>{if(e.target.id==='tryExperiment'&&e.target.open){if(!heroState)selectHero('ohm');else viewer?.resize?.();}if(e.target.id==='guidePanel'){prefs.layout.guidance=e.target.open;applyLayout();save();}if(e.target.id==='chartPanel'||e.target.id==='tablePanel'){prefs.layout[e.target.id==='chartPanel'?'chartCollapsed':'tableCollapsed']=!e.target.open;save();}},true);
document.addEventListener('input',e=>{const el=e.target;if(el.id==='heroVoltage'){updateHeroDemo();return;}if(el.id==='search'){catalogPage=1;search=el.value;renderCards();return}if(el.dataset.param){running=false;config.dragKey=el.dataset.param;state[el.dataset.param]=+el.value;clampState(active,state);syncControls();refresh();save();return}if(el.id==='time'){running=false;state.t=+el.value;refresh();save();return}if(el.id==='notes'||el.id==='prediction')save();});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='heroResistance'){updateHeroDemo();return;}if(el.dataset.number){const def=active.params.find(p=>p.key===el.dataset.number),value=String(el.value).trim(),n=Number(value);if(!value||!Number.isFinite(n)){syncControls();toast('Nhập một số cho '+def.label.toLowerCase()+'. Giá trị trước được giữ.');return;}running=false;config.dragKey=def.key;state[def.key]=Math.max(def.min,Math.min(def.max,n));clampState(active,state);syncControls();refresh();save();if(n<def.min||n>def.max)toast('Giới hạn '+def.label.toLowerCase()+': '+fmt(def.min,3)+'–'+fmt(def.max,3)+(def.unit?' '+def.unit:'')+'. Đã điều chỉnh về giới hạn.');}if(el.dataset.switch){config.switches[el.dataset.switch]=el.checked;refresh();save();}if(el.id==='catalogPageSelect'){goToCatalogPage(el.value);}if(el.id==='levelFilter'){catalogPage=1;levelFilter=el.value;renderCards();}if(el.id==='catalogSort'){catalogPage=1;catalogSort=el.value;renderCards();}if(el.id==='topic'){topic=el.value;renderCards();}if(el.id==='dragKey'){config.dragKey=el.value;syncControls();refresh();save();}if(el.dataset.progress!==undefined){prefs.progress=prefs.progress||{};prefs.progress[active.id]=prefs.progress[active.id]||[false,false,false];prefs.progress[active.id][+el.dataset.progress]=el.checked;save();}if(el.id==='sweepKey'){const p=sweepParameters().find(p=>p.key===el.value);$('#sweepStart').value=p.min;$('#sweepEnd').value=p.max;$('#sweepFixed').innerHTML='Giữ cố định: '+sweepFixed(el.value);}if(el.id==='graphMode'){config.graphMode=el.value;renderGraphOptions();renderGraph();save();}if(el.id==='graphX'||el.id==='graphY'){config[el.id]=+el.value;renderGraph();save();}if(el.id==='fitLine'){config.fitLine=el.checked;renderGraphOptions();renderGraph();save();}if(el.id==='fitModel'){config.fitModel=el.value;renderGraph();save();}if(el.id==='labSelect'){location.hash='#lab/'+el.value;}if(el.id==='motion'){prefs.motion=el.checked;if(active)refresh();else if(heroState)selectHero(heroState.id);save();}if(el.id==='speed')speed=+el.value;if(el.id==='gasAxis'){config.gasAxis=el.value;renderGraph();}if(el.id==='preset'&&el.value!==''){running=false;state={...initialState(active),...active.presets[+el.value].values};clampState(active,state);syncControls();refresh();save();}if(el.id==='quality'){prefs.quality=el.value;viewer?.quality(prefs.quality);save();}if(el.id==='textSize'){prefs.textSize=+el.value;document.documentElement.style.setProperty('--text-scale',prefs.textSize);save();}if(el.id==='voiceName'){prefs.voice=el.value;narrator.voiceName=el.value;save();}if(el.id==='voiceRate'){prefs.rate=+el.value;narrator.rate=+el.value;save();}if(el.id==='sessionFile'){const file=el.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error();const q=JSON.parse(await file.text());if(q.schema!=='thpt.session.v1'||q.id!==active.id||!Array.isArray(q.rows)||q.rows.length>500)throw Error();for(const r of q.rows){if(!Array.isArray(r.values)||r.values.length!==active.headers.length||r.values.some(v=>v!==null&&typeof v!=='number'&&typeof v!=='string')||r.values.some(v=>typeof v==='number'&&!Number.isFinite(v)))throw Error();}running=false;state=clampState(active,{...initialState(active),...q.state});rows=q.rows;config=importedConfig(q.config||{});pinned=null;saved[active.id]={state,rows,config,notes:String(q.notes||'').slice(0,20000),prediction:String(q.prediction||'').slice(0,2000)};if(Array.isArray(q.progress)&&q.progress.length===3){prefs.progress=prefs.progress||{};prefs.progress[active.id]=q.progress.map(Boolean);}if($('#notes'))$('#notes').value=saved[active.id].notes;if($('#prediction'))$('#prediction').value=saved[active.id].prediction;save();renderLab(active);toast('Đã mở phiên thí nghiệm.');}catch{toast('Tệp phiên không hợp lệ hoặc thuộc thí nghiệm khác.');}}});
$('#main').addEventListener('lab-render-error',e=>{recoverRenderer(e.detail?.message);if(active)refresh();});
$('#main').addEventListener('lab-context-lost',()=>{recoverRenderer('Thiết bị mất ngữ cảnh WebGL');if(active)refresh();});
window.addEventListener('hashchange',()=>{try{route();}catch(error){renderErrors.push(String(error));running=false;toast('Không mở được thí nghiệm này. Hãy thử quay về thư viện.');}});window.addEventListener('resize',()=>{applyLayout();});window.addEventListener('pageshow',()=>{if($('#bannerCanvas')&&!banner)mountBanner();});window.addEventListener('pagehide',()=>{stopBanner();save();narrator.stop();stopTone();});document.addEventListener('visibilitychange',()=>{if(document.hidden){running=false;save();stopTone();narrator.stop();}});
function animate(now){requestAnimationFrame(animate);const dt=last?Math.min(.07,(now-last)/1000):0;last=now;if(document.hidden)return;sceneAccumulator+=dt;uiAccumulator+=dt;try{if(!active&&heroState&&$('#tryExperiment')?.open&&$('#heroCanvas')&&viewer&&prefs.motion){heroState.s.t+=dt*.3;if(sceneAccumulator>=1/30){viewer.update(heroState.id,heroState.s,evaluate(heroState.id,heroState.s),{hero:true,motion:prefs.motion,switches:defaults.switches});sceneAccumulator=0;}}if(running&&active){state.t=(state.t||0)+dt*speed*(active.playSeconds?duration(active,state,getData())/active.playSeconds:(active.timeScale||1));let d=getData();const max=duration(active,state,d);if(state.t>=max){if(config.loop||active.visualOnly){state.t=state.t%max;}else{state.t=max;running=false;save();}d=getData();}if(sceneAccumulator>=1/30){if(viewer&&!viewFailed)viewer.update(active.id,state,d,{...config,motion:prefs.motion});sceneAccumulator=0;}if(uiAccumulator>=.10||!running){refresh();uiAccumulator=0;}}}catch(error){renderErrors.push(String(error));recoverRenderer(error);if(active)refresh();toast('Đã chuyển sang chế độ sơ đồ.');}}
$('#dialog').addEventListener('close',restoreDialogFocus);
if(!Array.isArray(prefs.favorites))prefs.favorites=[];if(!Array.isArray(prefs.recent))prefs.recent=[];prefs.progress=prefs.progress||{};document.documentElement.style.setProperty('--text-scale',prefs.textSize);route();requestAnimationFrame(animate);

const assistantLibrary=libraryContext(experiments);
const assistantContext=()=>active?{id:active.id,title:active.title,catalog:assistantLibrary,formula:active.formula,conditions:active.limit,configuration:{electricMode:active.id==='electric'?electricModes[config.mode]:undefined,capacitorMode:active.id==='capacitor'?config.capMode:undefined},parameters:active.params.map(p=>({key:p.key,label:p.label,value:state[p.key],unit:p.unit})),columns:active.headers,measurements:rows.slice(-12).map(r=>r.values)}:assistantLibrary;
assistant=new LabAssistant({getContext:assistantContext});
